/**
 * next/image loader for the static export: points at width variants pre-generated by
 * scripts/image-variants.mjs (public/images/<name>-w<width>.webp). Other paths are served as is.
 */
export default function imageLoader({ src, width }: { src: string; width: number }) {
  if (src.startsWith("/images/") && src.endsWith(".webp")) return src.replace(/\.webp$/, `-w${width}.webp`);
  return src;
}
